args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person (COALESCE(?bd, ?bd2) AS ?birthDate) ?label WHERE {
  VALUES ?person { dbr:Lorenzo_Zazzeri <http://dbpedia.org/resource/Eli%C5%A1ka_Kr%C3%A1snohorsk%C3%A1> }
  OPTIONAL { ?person dbo:birthDate ?bd. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  OPTIONAL { ?person rdfs:label ?label. FILTER(lang(?label) = 'en') }
}
ORDER BY DESC(?birthDate)
LIMIT 1

